42	package hotel.reservations;
43	
44	import hotel.rooms.Room;
45	import java.math.BigDecimal;
46	import java.math.RoundingMode;
47	import java.time.LocalDate;
48	import java.time.Month;
49	
50	/**
51	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
52	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
53	 * (half-even) at every step.
54	 */
55	public final class PriceCalculator {
56	
57	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
58	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
59	
60	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
61	        int nights = 0;
62	        BigDecimal subtotal = cents(BigDecimal.ZERO);
63	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
64	            subtotal = subtotal.add(nightPrice(room, night));
65	            nights++;
66	        }
67	        BigDecimal discount = switch (ratePlan) {
68	            case STANDARD -> cents(BigDecimal.ZERO);
69	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
70	        };
71	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
72	    }
73	
74	    BigDecimal nightPrice(Room room, LocalDate night) {
75	        BigDecimal nightlyRate = room.nightlyRate();
76	        if (isHighSeason(night)) {
77	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
78	        }
79	        return cents(nightlyRate);
80	    }
81	
82	    /** High season: from December 15 to the end of February, and the whole of July. */
83	    static boolean isHighSeason(LocalDate date) {
84	        Month month = date.getMonth();
85	        return month == Month.JANUARY
86	                || month == Month.FEBRUARY
87	                || month == Month.JULY
88	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
89	    }
90	
91	    static BigDecimal cents(BigDecimal value) {
92	        return value.setScale(2, RoundingMode.HALF_EVEN);
93	    }
94	}
