231	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
232	public final class ReservationService {
233	
234	    static final String HOTEL_NAME = "Pousada Maré Alta";
235	
236	    private final Rooms rooms;
237	    private final ReservationStore store;
238	    private final PriceCalculator priceCalculator;
239	    private final EmailSender emailSender;
240	
241	    public ReservationService(
242	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
243	        this.rooms = rooms;
244	        this.store = store;
245	        this.priceCalculator = priceCalculator;
246	        this.emailSender = emailSender;
247	    }
248	
249	    public synchronized Reservation create(NewReservation request) {
250	        if (!request.checkOut().isAfter(request.checkIn())) {
251	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
252	        }
253	        if (request.guests() < 1) {
254	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
255	        }
256	        Room room = rooms.find(request.roomNumber())
257	                .orElseThrow(() -> new HotelException(
258	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
259	        if (request.guests() > room.capacity()) {
260	            throw new HotelException(
261	                    ErrorCode.CAPACITY_EXCEEDED,
262	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
263	        }
264	        boolean roomTaken = store.all().stream()
265	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
266	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
267	        if (roomTaken) {
268	            throw new HotelException(
269	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
270	        }
271	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
272	        Reservation reservation = new Reservation(store.nextId(), request, price);
273	        store.save(reservation);
274	        return reservation;
275	    }
276	
277	    public Reservation find(long reservationId) {
278	        return store.find(reservationId)
279	                .orElseThrow(() -> new HotelException(
280	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
281	    }
282	
283	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
284	    public synchronized Reservation confirm(long reservationId) {
285	        Reservation reservation = find(reservationId);
286	        if (reservation.status() != ReservationStatus.PENDING) {
287	            throw notAllowed(reservation, "confirm");
288	        }
289	        reservation.confirmPayment();
290	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
291	        emailSender.send(
292	                reservation.guest().email(),
293	                "Reserva confirmada - " + HOTEL_NAME,
294	                confirmationEmailBody(reservation, receipt));
295	        return reservation;
296	    }
297	
298	    /**
299	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
300	     * reservation was never paid, so nothing comes back).
301	     */
302	    public synchronized Reservation cancel(long reservationId) {
303	        Reservation reservation = find(reservationId);
304	        if (reservation.status() != ReservationStatus.PENDING
305	                && reservation.status() != ReservationStatus.CONFIRMED) {
306	            throw notAllowed(reservation, "cancel");
307	        }
308	        BigDecimal refund = switch (reservation.ratePlan()) {
309	            case STANDARD -> reservation.amountPaid();
310	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
311	        };
312	        reservation.cancel(refund);
313	        return reservation;
314	    }
315	
316	    public synchronized Reservation checkIn(long reservationId) {
317	        Reservation reservation = find(reservationId);
318	        if (reservation.status() != ReservationStatus.CONFIRMED) {
319	            throw notAllowed(reservation, "check in");
320	        }
321	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
322	        return reservation;
323	    }
324	
325	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
326	    public synchronized ReservationReceipt checkOut(long reservationId) {
327	        Reservation reservation = find(reservationId);
328	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
329	            throw notAllowed(reservation, "check out");
330	        }
331	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
332	        return new ReservationReceipt(reservation, roomOf(reservation));
333	    }
334	
335	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
336	    public ReservationReceipt receiptCopy(long reservationId) {
337	        Reservation reservation = find(reservationId);
338	        if (!reservation.isPaid()) {
339	            throw notAllowed(reservation, "issue a receipt for");
340	        }
341	        return new ReservationReceipt(reservation, roomOf(reservation));
342	    }
