349	        return "Olá, " + reservation.guest().name() + "!\n\n"
350	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
351	                + receipt.text() + "\n"
352	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
353	                + "Até breve!\n";
354	    }
