    @Test
    void corporateTakesTheDiscountOfTheGuestsCompany() {
        Price tecnosul = price(
                deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "TECNOSUL");

        // 12% of 779.80 = 93.576
        assertEquals(new BigDecimal("779.80"), tecnosul.subtotal());
        assertEquals(new BigDecimal("93.58"), tecnosul.discount());
        assertEquals(new BigDecimal("686.22"), tecnosul.total());

        Price agrovale = price(
                deluxe, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "AGROVALE");
        Price farmavida = price(
                suite, LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "FARMAVIDA");

        // 18% of 779.80 = 140.364; 25% of 1159.80 = 289.95
        assertEquals(new BigDecimal("140.36"), agrovale.discount());
        assertEquals(new BigDecimal("289.95"), farmavida.discount());
        assertEquals(new BigDecimal("869.85"), farmavida.total());
    }

    @Test
    void theWeekendPackageHasAFixedPricePerRoomType() {
        Price deluxePackage = price(
                deluxe, LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), RatePlan.WEEKEND_PACKAGE);

        assertEquals(2, deluxePackage.nights());
        assertEquals(new BigDecimal("820.00"), deluxePackage.subtotal());
        assertEquals(new BigDecimal("0.00"), deluxePackage.discount());
        assertEquals(new BigDecimal("820.00"), deluxePackage.total());

        // the same price in high season
        assertEquals(new BigDecimal("520.00"), price(
                standardRoom, LocalDate.of(2027, 7, 9), LocalDate.of(2027, 7, 11), RatePlan.WEEKEND_PACKAGE).total());
        assertEquals(new BigDecimal("1200.00"), price(
                suite, LocalDate.of(2027, 7, 9), LocalDate.of(2027, 7, 11), RatePlan.WEEKEND_PACKAGE).total());
    }

    @Test
    void longStayTakes10PercentOff() {
        Price price = price(
                standardRoom, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 8), RatePlan.LONG_STAY);

        assertEquals(7, price.nights());
        assertEquals(new BigDecimal("1749.30"), price.subtotal());
        assertEquals(new BigDecimal("174.93"), price.discount());
        assertEquals(new BigDecimal("1574.37"), price.total());
    }

    @Test
    void longStayDiscountIsOnTheHighSeasonPrice() {
        Price price = price(
                standardRoom, LocalDate.of(2027, 2, 25), LocalDate.of(2027, 3, 4), RatePlan.LONG_STAY);

        // February 25 to 28: 4 x 299.88; March 1 to 3: 3 x 249.90; 10% of 1949.22 = 194.922
        assertEquals(new BigDecimal("1949.22"), price.subtotal());
        assertEquals(new BigDecimal("194.92"), price.discount());
        assertEquals(new BigDecimal("1754.30"), price.total());
    }
}
